(async()=>{const worker=await new Promise((resolve,reject)=>{const u=URL.createObjectURL(new Blob(['onmessage=()=>postMessage({language:navigator.language,languages:navigator.languages})'])),w=new Worker(u);w.onmessage=e=>{w.terminate();URL.revokeObjectURL(u);resolve(e.data)};w.onerror=e=>reject(Error(e.message));w.postMessage(null)});return {window:{language:navigator.language,languages:navigator.languages},worker}})()
